      const speed = 100 + Math.random() * (success ? 320 : 520);
      dots.push({ x, y, vx: Math.cos(angle) * speed, vy: Math.sin(angle) * speed, color: colors[i % colors.length], size: 2 + Math.random() * (success ? 3 : 10) });
